// RoundTrip injects JWT bearer token in every outgoing request.
func (t *jwtTransport) RoundTrip(req *http.Request) (*http.Response, error) {
    claims := jwt.MapClaims{
        "iat": time.Now().Unix(),  // +/- 5 seconds from server verification
    }
    if len(t.jwtId) > 0 {
        claims["id"] = t.jwtId
    }
    token := jwt.NewWithClaims(jwt.SigningMethodHS256, claims)
    tokenString, err := token.SignedString(t.jwtSecret)
    if err != nil { return nil, errors.Wrap(err, "could not produce signed JWT token") }
    req.Header.Set("Authorization", "Bearer "+tokenString)
    return t.underlyingTransport.RoundTrip(req)
}

